    ]);
    const { lastFrame } = render(<Dashboard state={state} selectedIndex={0} now={NOW} />);
    const frame = lastFrame() ?? '';
    expect(frame).toContain('3 lane(s)');
    expect(frame).toContain('#296');
    expect(frame).toContain('#301');
    expect(frame).toContain('#305');
